              let nav_active_mask = $("#nav__active-mask");
              var hamburger = $(".nav-hamburger-wrapper");
              var purple_menu = $(".nav__bar");
              var sm_menu_panel = $("#nav--sm__panel");
              var menu_text = $("#menu-toggle");
              const nav__banner = $(".nav__banner");
              if (hamburger) {
