                  e.preventDefault();
                  if (true !== menu_active) {
                    menu_active = true;
                    hamburger.addClass("active");
                    menu_text.text("CLOSE");
                    purple_menu.addClass("active");
                    nav_active_mask.removeClass("inactive");
                    sm_menu_panel.removeClass('inactive').one('transitionend', function(e) {
                      $("body").addClass("locked");
